16	    public static DirectedGraph fromEdges(int vertexCount, List<Edge> edges) {
17	        if (edges == null) {
18	            throw new IllegalArgumentException("Edges must not be null.");
19	        }
20	
21	        List<List<Integer>> adjacency = createEmptyAdjacency(vertexCount);
22	
23	        for (Edge edge : edges) {
24	            validateEdge(edge);
25	
26	            int from = edge.from();
27	            int to = edge.to();
28	            validateVertex(from, vertexCount);
29	            validateVertex(to, vertexCount);
30	            adjacency.get(from).add(to);
31	        }
32	
33	        return new DirectedGraph(freeze(adjacency));
34	    }
35	
36	    @Override
37	    public int vertexCount() {
38	        return adjacency.size();
39	    }
40	
41	    @Override
42	    public List<Integer> neighborsOf(int vertex) {
43	        validateVertex(vertex, vertexCount());
44	        return adjacency.get(vertex);
45	    }
46	
47	    @Override
48	    public DirectedGraph reverse() {
49	        List<List<Integer>> reversedAdjacency = createEmptyAdjacency(vertexCount());
50	
51	        for (int vertex = 0; vertex < vertexCount(); vertex++) {
52	            for (int neighbor : neighborsOf(vertex)) {
53	                reversedAdjacency.get(neighbor).add(vertex);
54	            }
55	        }
56	
57	        return new DirectedGraph(freeze(reversedAdjacency));
58	    }
