60	    private static List<List<Integer>> createEmptyAdjacency(int vertexCount) {
61	        if (vertexCount < 0) {
62	            throw new IllegalArgumentException("Vertex count must be non-negative.");
63	        }
64	
65	        List<List<Integer>> adjacency = new ArrayList<>(vertexCount);
66	        for (int vertex = 0; vertex < vertexCount; vertex++) {
67	            adjacency.add(new ArrayList<>());
68	        }
69	        return adjacency;
70	    }
