72	    private static List<List<Integer>> freeze(List<List<Integer>> adjacency) {
73	        List<List<Integer>> immutableAdjacency = new ArrayList<>(adjacency.size());
74	
75	        for (List<Integer> neighbors : adjacency) {
76	            immutableAdjacency.add(List.copyOf(neighbors));
77	        }
78	
79	        return Collections.unmodifiableList(immutableAdjacency);
